const OMPL = (n: number, a: [string, string, string]) => { const m = n % 100, k = n % 10; return `${n} ${m > 10 && m < 20 ? a[2] : k === 1 ? a[0] : k > 1 && k < 5 ? a[1] : a[2]}`; };
