const ORGGO: Record<string, string> = {}; ORGG.forEach(([g, , os]) => os.forEach((o) => { ORGGO[o] = g; }));
const ORGC = (dk: boolean) => (dk ? '#4FC3D9' : '#0B7C93');
/* П14 (12.11.2026): цвета органов разведены по оттенку (палитра Окабэ–Ито, различима при дальтонизме): Минюст — пурпурный вместо второго оливкового */
const ORGGC: Record<string, [string, string]> = { par: ['#0B7C93', '#4FC3D9'], pg: ['#A3302A', '#FF8A80'], eco: ['#7F5AB5', '#B69CE6'], inf: ['#C2570C', '#FF9A57'], soc: ['#8A6E00', '#D9BE45'], law: ['#B8407A', '#F08DC0'] };
const grpCol = (g: string, dk: boolean) => (ORGGC[g] ? ORGGC[g][dk ? 1 : 0] : ORGC(dk));
const orgCol = (o: string, dk: boolean) => grpCol(ORGGO[o], dk); /* цвет органа — цвет его группы */
